VERSION = '1.0.2'
SYSTEM_SCHEMAS = ('mysql', 'information_schema', 'performance_schema', 'ndbinfo', 'ndbmemcache', 'sys')
GENERATORS = ('gen_schemes_script', 'gen_table_script', 'gen_data_script',
              'gen_view_script', 'gen_triggers_script', 'gen_event_script')
DEFAULT_PATTERNS = ['%copy', '%copy1', '%copy2', '%copy3', 'alter_table', '%transfer_casino_balance_shard%']
RESOURCES = {
'gen_data_script.sql': r"""DROP PROCEDURE IF EXISTS  `tools`.`gen_data_script`;

delimiter $$
CREATE DEFINER=`Sup_User_SPESA`@`%` PROCEDURE `tools`.`gen_data_script`(IN SchemeName VARCHAR(64), in tableName VARCHAR(1000), in EngineName varchar(64))  ExitSub:BEGIN
-- CALL tools.gen_data_script('SchemeName', tableName, EngineName);
-- CALL tools.gen_data_script('', '', ''); -- All tables
-- CALL tools.gen_data_script('SchemeName', '', ''); -- All tables for particular schema
-- CALL tools.gen_data_script('SchemeName', 'tableName', ''); -- Only for particular table
-- CALL tools.gen_data_script('', '', 'EngineName'); -- Only for particular engine
-- CALL tools.gen_data_script('SchemeName', '', 'EngineName'); -- Only for particular engine and schema

	DECLARE errNom INT DEFAULT 0;
	DECLARE errText, MysqlVer VARCHAR(255) DEFAULT '';

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
			GET DIAGNOSTICS CONDITION 1 errText = MESSAGE_TEXT ,errNom = MYSQL_ERRNO;
			SELECT errNom, errText;
		END;

SET MysqlVer = VERSION();

SET SESSION group_concat_max_len = 50000;
SELECT
	CONCAT( 'mysqldump -P 3306 -hlocalhost -udba -pdba --no-create-db --no-create-info', IF(LEFT(MysqlVer, 2) = '5.', '', ' --column-statistics=0'), ' --skip-triggers --extended-insert --default-character-set=utf8mb4 --no-tablespaces --databases ',
	TABLE_SCHEMA, ' ', IF(tableName<>'', REPLACE ( GROUP_CONCAT( TABLE_NAME ), ',', ' ' ), ' ' ), ' > backup_', @@hostname, '_', TABLE_SCHEMA, '_data.sql' ) as data_gen_script
FROM information_schema.`TABLES` 
WHERE	`ENGINE` = IF(EngineName='', `ENGINE`, EngineName) 
		 AND TABLE_SCHEMA NOT IN ( 'information_schema', 'performance_schema', 'mysql', 'ndbinfo', '_development', '_test') 
		 AND TABLE_SCHEMA = IF(SchemeName='', TABLE_SCHEMA, SchemeName)
		 AND TABLE_NAME   = IF(tableName='', TABLE_NAME, tableName) 
GROUP BY	TABLE_SCHEMA ORDER BY TABLE_SCHEMA, TABLE_NAME;

END$$
delimiter ;
""",
'gen_event_script.sql': r"""USE tools;
DROP PROCEDURE IF EXISTS `tools`.`gen_event_script`;
DELIMITER $$

CREATE DEFINER=`Sup_User_SPESA`@`%` PROCEDURE `gen_event_script`(IN SchemaName VARCHAR(64), IN EventName VARCHAR(64))
    COMMENT 'Create backup of all procedure every 2 days'
ExitSub:BEGIN
	DECLARE errNom INT DEFAULT 0;
   DECLARE errText VARCHAR(255) DEFAULT '';
	-- call tools.gen_event_script('bets', 'bets_settle'); -- Get only specific event
	-- call tools.gen_event_script('bets', 			  ''); -- Get all events for specific schema
	-- call tools.gen_event_script(''	 , 			  ''); -- Get all events for all schemas

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
			GET DIAGNOSTICS CONDITION 1 errText = MESSAGE_TEXT ,errNom = MYSQL_ERRNO;
			SELECT errNom, errText;
		END;	

	SET SESSION sql_mode="NO_ENGINE_SUBSTITUTION";
	SET @@group_concat_max_len = 20000000;
		  
	SELECT GROUP_CONCAT(
					 CONCAT(
								'DROP EVENT IF EXISTS ', ' `', EVENT_SCHEMA, '`.`', EVENT_NAME, '`', ';\n',
								'delimiter $$ \nCREATE DEFINER=`Sup_User_SPESA`@`%` EVENT `', EVENT_SCHEMA, '`.`', EVENT_NAME, 
								'` ON SCHEDULE EVERY ', INTERVAL_VALUE, ' ', INTERVAL_FIELD, 
								' STARTS \'', STARTS, '\' ',
								'ON COMPLETION ', REPLACE(ON_COMPLETION, 'DROP', 'NOT PRESERVE'), ' ', 
								REPLACE(REPLACE(STATUS, 'DISABLED', 'DISABLE'), 'ENABLED', 'ENABLE'), 
								' COMMENT "',
								REPLACE(REPLACE(EVENT_COMMENT, '"', '\\"'), "'", "\\'"),
								'" ',
								'DO ', EVENT_DEFINITION, ';$$\n',
							   'delimiter ;'
							) ORDER BY EVENT_SCHEMA, EVENT_NAME
					  SEPARATOR '\n\n'
							) as events_script
		 FROM information_schema.EVENTS 
		 WHERE EVENT_SCHEMA = IF(SchemaName<>'', SchemaName, EVENT_SCHEMA) AND EVENT_NAME = IF(EventName<>'', EventName, EVENT_NAME);
END $$ 
DELIMITER ;
