'gen_table_script.sql': r"""DROP PROCEDURE IF EXISTS  `tools`.`gen_table_script`;

delimiter $$
CREATE DEFINER=`Sup_User_SPESA`@`%` PROCEDURE `tools`.`gen_table_script`(IN act int, in tableschema VARCHAR(64), in tableName VARCHAR(64), in EngineName varchar(64), in CharacterName VARCHAR(64), IN CollationNam VARCHAR(64) )  ExitSub:BEGIN
-- call tools.gen_table_script(1, '', '', '', '', ''); -- Backup all tables from all schemas
-- call tools.gen_table_script(1, 'database name', '', '', '', ''); -- Backup all tables for particular schema
-- call tools.gen_table_script(1, '', '', 'engine name', '', ''); -- Backup all tables for for related engine
-- call tools.gen_table_script(1, 'database name', '', 'engine name', '', ''); -- Backup for particular schema and only for related engine
-- call tools.gen_table_script(1, 'database name', 'table name', '', '', ''); -- Backup for only particular table
-- call tools.gen_table_script(1, '', '', '', 'add character set', 'add collation'); -- change all columns option and table option to use defined "CHARACTER SET" and "COLLATION". This option can be add for all actions
	DECLARE errNom, RowNo INT DEFAULT 0;
   DECLARE errText VARCHAR(255) DEFAULT '';
	DECLARE TableType, `TabEngine`, ColumnName, DataType, NameSchema, NameTable, LastTable, LastSchema VARCHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE PrimaryKeyDef VARCHAR(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE TableCollation VARCHAR(32) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE EngineParam VARCHAR(32) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL;
	DECLARE RowFormat VARCHAR(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE TableComment, IndexDef, ForeignKey VARCHAR(2048) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE SchemaNames VARCHAR(21845) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE TablesNames text CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE TablesScript longtext CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE AllColumn MEDIUMTEXT CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
      GET DIAGNOSTICS CONDITION 1 errText = MESSAGE_TEXT ,errNom = MYSQL_ERRNO;
		SELECT RowNo, errNom, errText, NameSchema, TablesNames, NameTable, TablesScript, @createtable;
		END;

	SET @@group_concat_max_len = 30000000;

	IF act= 1 THEN -- BY ENGINE or ALL
	
		IF tableschema<>'' AND TableName<>'' THEN -- Get only particular table
			SET RowNo=2;
			SELECT TABLE_TYPE, `ENGINE`, ROW_FORMAT, TABLE_COLLATION, TABLE_COMMENT INTO TableType, `TabEngine`, RowFormat, TableCollation, TableComment
				FROM information_schema.`TABLES` WHERE TABLE_SCHEMA=TableSchema AND TABLE_NAME=TableName AND TABLE_SCHEMA NOT IN('mysql', 'information_schema', 'performance_schema', 'ndbinfo', 'ndbmemcache', 'sys') LIMIT 1;	

			SET NameSchema=TableSchema, NameTable=TableName;

			IF TableName IS NULL THEN
				SELECT 'info' as res, 'Not exists table!' as description; LEAVE ExitSub;
			END IF;
		ELSE -- Get by Schema and or Engine
			SET @TablesNames=NULL;
			IF EngineName <> '' THEN
				SET EngineParam = CONCAT(' AND `ENGINE` = "', EngineName, '";');
			ELSE
				SET EngineParam = ';';
			END IF;
			
			SET RowNo=4;
			IF tableschema<>'' THEN
				SELECT SCHEMA_NAME INTO SchemaNames FROM information_schema.`SCHEMATA` WHERE SCHEMA_NAME=tableschema AND SCHEMA_NAME NOT IN('mysql', 'information_schema', 'performance_schema', 'ndbinfo', 'ndbmemcache', 'sys');
			ELSE
				SELECT GROUP_CONCAT(SCHEMA_NAME) INTO SchemaNames FROM information_schema.`SCHEMATA` WHERE SCHEMA_NAME NOT IN('mysql', 'information_schema', 'performance_schema', 'ndbinfo', 'ndbmemcache', 'sys');
			END IF;
			
			IF SchemaNames IS NULL THEN SELECT 'info' as res, 'Not exists SCHEMA!' as description; LEAVE ExitSub; END IF;
		END IF;

		ExitL:LOOP
			IF TableName='' THEN -- Get by Schema and or Engine
				SET RowNo=6;
				SET NameSchema=SUBSTRING_INDEX(SchemaNames,',',1);
				IF NameSchema=LastSchema THEN /*SELECT 73, TablesScript, NameSchema, LastSchema, 'info' as res, 'Last Schema!' as description;*/ LEAVE ExitL; END IF;
				SET LastSchema=NameSchema;
				SET SchemaNames=TRIM(LEADING CONCAT(NameSchema, ',') FROM SchemaNames);

				SET @SqlSt=CONCAT('SELECT GROUP_CONCAT(TABLE_NAME) INTO @TablesNames FROM information_schema.`TABLES` WHERE TABLE_SCHEMA="', NameSchema, '" AND TABLE_TYPE<>"VIEW"', EngineParam);

				SET rowNo=8; PREPARE stmt FROM @SqlSt; EXECUTE stmt; DEALLOCATE PREPARE stmt;
	-- SELECT 1, @SqlSt, @TablesNames; LEAVE ExitSub;			
				IF @TablesNames IS NULL THEN /*SELECT 79, 'info' as res, 'Not exists Tables!' as description, NameSchema, SchemaNames, @TablesNames;*/ ITERATE ExitL; END IF;
			END IF;
-- 			SET @cnt=0;
			ExitL2:LOOP
				IF TableName='' THEN
					SET NameTable=SUBSTRING_INDEX(@TablesNames, ',', 1);
					SET RowNo=10;
					IF LastTable=NameTable THEN /*SELECT 83, NameSchema, SchemaNames, @TablesNames, LastTable, NameTable;*/ LEAVE ExitL2; END IF;
					
					SET LastTable=NameTable;
					SET @TablesNames=TRIM(LEADING CONCAT(NameTable, ',') FROM @TablesNames);
					SET RowNo=12;
					SET TableType='', `TabEngine`='', RowFormat='', TableCollation='', TableComment='';
					SELECT TABLE_TYPE, `ENGINE`, ROW_FORMAT, TABLE_COLLATION, TABLE_COMMENT INTO TableType, `TabEngine`, RowFormat, TableCollation, TableComment
						FROM information_schema.`TABLES` WHERE TABLE_SCHEMA=NameSchema AND TABLE_NAME=NameTable LIMIT 1;	
				END IF;

				SET TableComment=REPLACE(TableComment, "'", "");
				SET RowNo=14;				
				SET @createtable='', AllColumn='', PrimaryKeyDef='', IndexDef='';

				SELECT REPLACE(GROUP_CONCAT(
				  CONCAT(IF(COLUMN_TYPE='geometry', '\n', '\n`'), 
							IF(COLUMN_TYPE='geometry', CONCAT('/*!50705 `', COLUMN_NAME), COLUMN_NAME), 
							'` ', 
							IF(COLUMN_TYPE='geometry', CONCAT(COLUMN_TYPE, ' */ /*!80003 SRID 0 */ /*!50705 '), COLUMN_TYPE),
							IF(CHARACTER_SET_NAME IS NOT NULL,  IF(CharacterName<>'', CONCAT(' CHARACTER SET ', CharacterName, ' '), CONCAT(' CHARACTER SET ', CHARACTER_SET_NAME, ' ') ), ''), 
							IF(COLLATION_NAME IS NOT NULL, IF(CollationNam<>'', CONCAT(' COLLATE ', CollationNam, ' '), CONCAT(' COLLATE ', COLLATION_NAME, ' ')), ''), 		
							IF(IS_NULLABLE='NO', ' NOT NULL ', ' NULL '),
							IF(COLUMN_DEFAULT IS NULL, '',  CONCAT(' DEFAULT ', IF(COLUMN_DEFAULT='', "''", IF(COLUMN_DEFAULT='CURRENT_TIMESTAMP ', CONCAT(COLUMN_DEFAULT, " "), CONCAT("'", REPLACE(COLUMN_DEFAULT, "'", "''"), "'"))      ))),
							-- IF(EXTRA<>'' AND EXTRA <> 'DEFAULT_GENERATED', CONCAT(' ', EXTRA, ' '), ''),
							REPLACE(EXTRA, 'DEFAULT_GENERATED', ''),
										IF(COLUMN_COMMENT<>'', CONCAT(' COMMENT \'', REPLACE(COLUMN_COMMENT, "'", ""), '\' '), ''), IF(COLUMN_TYPE='geometry', ',*/,,,&*YG^&', '')) ORDER BY ORDINAL_POSITION
							), ',,,&*YG^&,', '' ) INTO AllColumn
				FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = NameSchema AND TABLE_NAME = NameTable ORDER BY ORDINAL_POSITION;

				SET RowNo=18;
				SELECT IFNULL(CONCAT('\nPRIMARY KEY (', GROUP_CONCAT('`', COLUMN_NAME, '`' ORDER BY SEQ_IN_INDEX),')', IF(INDEX_TYPE='BTREE', ' USING BTREE,', ',')), '') INTO PrimaryKeyDef FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=NameSchema AND TABLE_NAME = NameTable AND INDEX_NAME='PRIMARY';	
				SET RowNo=20;
				SELECT IFNULL(REPLACE(GROUP_CONCAT(t1.Def), '*/,', '*/'), '') INTO IndexDef FROM
				(SELECT CONCAT(IF(NON_UNIQUE=0, '\nUNIQUE KEY `', IF(INDEX_TYPE = 'SPATIAL', '\n/*!50705 SPATIAL KEY `',  IF(INDEX_TYPE = 'FULLTEXT', '\nFULLTEXT KEY `', '\nKEY `'))),				
										INDEX_NAME, 
										'` (', 
										GROUP_CONCAT('`', COLUMN_NAME, '`', IF(SUB_PART IS NOT NULL AND INDEX_TYPE <> 'SPATIAL', CONCAT('(', SUB_PART, ')'), '') ORDER BY SEQ_IN_INDEX),
										')', 
										IF(INDEX_TYPE = 'SPATIAL', ',*/', ''),
										IF(INDEX_TYPE='BTREE', ' USING BTREE', '')
								  ) as Def 
					FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=NameSchema AND TABLE_NAME = NameTable AND INDEX_NAME<>'PRIMARY' GROUP BY INDEX_NAME) as t1; 

				IF IndexDef='' THEN SET PrimaryKeyDef=TRIM(TRAILING ',' FROM PrimaryKeyDef); END IF;
					
				IF PrimaryKeyDef<>'' OR IndexDef<>'' THEN SET AllColumn=CONCAT(AllColumn, ','); END IF;
				
				-- GET FOREIGN KEY
				SELECT IFNULL(GROUP_CONCAT(t1.Foreign_Key), '') INTO ForeignKey FROM
				(SELECT CONCAT('\nCONSTRAINT `', RefCons.CONSTRAINT_NAME, '` FOREIGN KEY (`', KeyCol.COLUMN_NAME, '`) REFERENCES `', RefCons.REFERENCED_TABLE_NAME, '` (`', KeyCol.REFERENCED_COLUMN_NAME, '`)' 
				, IF(RefCons.DELETE_RULE<>'NONE', CONCAT(' ON DELETE ', RefCons.DELETE_RULE), ' '), IF(RefCons.UPDATE_RULE<>'NONE', CONCAT(' ON UPDATE ', RefCons.UPDATE_RULE), ' ') ) as Foreign_Key
				FROM information_schema.referential_constraints RefCons
				JOIN information_schema.key_column_usage KeyCol ON RefCons.constraint_schema = KeyCol.table_schema
				-- LEFT JOIN information_schema.INNODB_SYS_FOREIGN -- -- 0 = ON DELETE/UPDATE RESTRICT, 1 = ON DELETE CASCADE, 2 = ON DELETE SET NULL, 4 = ON UPDATE CASCADE, 8 = ON UPDATE SET NULL, 16 = ON DELETE NO ACTION, 32 = ON UPDATE NO ACTION.
					  AND RefCons.table_name = KeyCol.table_name
					  AND RefCons.constraint_name = KeyCol.constraint_name
						WHERE RefCons.constraint_schema=NameSchema AND RefCons.TABLE_NAME=NameTable) as t1;

				SET RowNo=22;
-- 				SET @createtable=CONCAT('USE `', NameSchema, '`;\nCREATE TABLE IF NOT EXISTS `', NameSchema, '`.`', NameTable,'` (', AllColumn, PrimaryKeyDef, IF(ForeignKey<>'', CONCAT(IndexDef, ','), IndexDef), ForeignKey, '\n)ENGINE = ', TabEngine,
					SET @createtable=CONCAT('USE `', NameSchema, '`;\nCREATE TABLE IF NOT EXISTS `', NameSchema, '`.`', NameTable,'` (', AllColumn, PrimaryKeyDef, IF(ForeignKey<>'', IF(SUBSTRING_INDEX(IndexDef, ',', -1)= '*/', IndexDef, CONCAT(IndexDef, ',')), IndexDef), ForeignKey, '\n)ENGINE = ', TabEngine,
												' CHARACTER SET = ', IF(CharacterName<>'', CharacterName, SUBSTRING_INDEX(TableCollation,'_',1) ), ' COLLATE = ', IF(CollationNam<>'', CollationNam , TableCollation), ' ROW_FORMAT = ', RowFormat,
												IF(TableComment<>'', CONCAT(' COMMENT \'', TableComment, '\' '), ''), ';\n\n');			
				
				IF TableName<>'' THEN -- If condition has only one particular table
					SELECT @createtable; Leave ExitSub;
				END IF;							
												
				SET RowNo=24;
				SET TablesScript=CONCAT(TablesScript, @createtable);
				IF TablesScript IS NULL THEN /*SELECT 139, TablesScript, @createtable, NameSchema, NameTable, AllColumn, PrimaryKeyDef, IndexDef, TabEngine;*/ LEAVE ExitSub; END IF;
-- 				SET @cnt=@cnt+1; IF @cnt>=200 THEN SELECT 123,  NameSchema, SchemaNames, @TablesNames, LastTable, NameTable; LEAVE ExitSub; END IF;
			END LOOP;
		END LOOP;
		
		SELECT CONCAT("SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;\nSET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;\nSET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='TRADITIONAL';\n", TablesScript) as TablesScript;
	END IF;
	
	IF act= 5 THEN -- Create VIEWS script
		SET RowNo=26;
		SELECT CONCAT("DROP VIEW IF EXISTS ", TABLE_SCHEMA, ".", TABLE_NAME, ";\nCREATE OR REPLACE VIEW ", TABLE_SCHEMA, ".", TABLE_NAME, " AS ", VIEW_DEFINITION, ";\n") table_name 
		FROM information_schema.views where TABLE_SCHEMA NOT IN("mysql", "information_schema", "performance_schema", "ndbinfo", "ndbmemcache", "sys");
	END IF;

END$$
delimiter ;
""",
'gen_triggers_script.sql': r"""DROP PROCEDURE IF EXISTS  `tools`.`gen_triggers_script`;

delimiter $$
CREATE DEFINER=`Sup_User_SPESA`@`%` PROCEDURE `gen_triggers_script`(IN SchemaName VARCHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci, IN TrigName VARCHAR(64))
ExitSub:BEGIN
	DECLARE errNom INT DEFAULT 0;
   DECLARE errText VARCHAR(255) DEFAULT '';
	-- call tools.gen_triggers_script('kannel', 'before_insert_inbox_kanel'); -- Only a specific trigger
	-- call tools.gen_triggers_script('kannel', ''); -- Triggers by schema
	-- call tools.gen_triggers_script('', ''); -- All triggers
	DECLARE RowNo INT DEFAULT 0;
	DECLARE FullScript LONGTEXT CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';
	DECLARE BySchemaNameCon, ByTrigNameCon VARCHAR(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '';

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
      GET DIAGNOSTICS CONDITION 1 errText = MESSAGE_TEXT ,errNom = MYSQL_ERRNO;
				SELECT RowNo, errNom, errText;
		END;

	SET SESSION sql_mode="NO_ENGINE_SUBSTITUTION", @@group_concat_max_len = 1000000;
	
	IF SchemaName <> '' AND TrigName <> '' THEN -- Only a specific trigger 
		SET BySchemaNameCon = CONCAT("where	TRIGGER_SCHEMA='", SchemaName, "'");
		SET ByTrigNameCon = CONCAT(" AND TRIGGER_NAME='", TrigName, "' limit 1;");
	ELSEIF SchemaName <> '' AND TrigName = '' THEN -- Triggers by schema
		SET BySchemaNameCon = CONCAT("where	TRIGGER_SCHEMA='", SchemaName, "' ORDER BY TRIGGER_NAME;");
	ELSE
		SET @@group_concat_max_len = 1000000;
		SET ByTrigNameCon = 'ORDER BY TRIGGER_SCHEMA, TRIGGER_NAME;'; -- All triggers
	END IF;		

	SET @SqlSt=CONCAT("SELECT GROUP_CONCAT(CONCAT('DROP TRIGGER IF EXISTS ', ' `', TRIGGER_SCHEMA, '`.`', `TRIGGER_NAME`, '`', ';\ndelimiter $$\nCREATE DEFINER=`Sup_User_SPESA`@`%` TRIGGER `', TRIGGER_SCHEMA, '`.`', `TRIGGER_NAME`,'` ', ACTION_TIMING, ' ', EVENT_MANIPULATION, ' ON `', EVENT_OBJECT_SCHEMA, '`.`', EVENT_OBJECT_TABLE,
			'` FOR EACH ', ACTION_ORIENTATION, ' ', ACTION_STATEMENT, '\n$$\ndelimiter ;') SEPARATOR '\n\n') as FullScript
				FROM information_schema.`TRIGGERS` ", BySchemaNameCon, ByTrigNameCon);
-- SELECT @SqlSt;
	SET rowNo=8; PREPARE stmt FROM @SqlSt; EXECUTE stmt; DEALLOCATE PREPARE stmt;
END$$

delimiter ;

""",
'gen_view_script.sql': r"""USE tools;
DROP PROCEDURE IF EXISTS `tools`.`gen_view_script`;
DELIMITER $$

CREATE DEFINER=`Sup_User_SPESA`@`%` PROCEDURE `tools`.`gen_view_script`(IN tableschema VARCHAR(64), IN ViewName VARCHAR(64))
ExitSub:BEGIN
-- call tools.gen_view_script('', '');                        -- Backup all views from all schemas
-- call tools.gen_view_script('database name', '');           -- Backup all views for particular schema
-- call tools.gen_view_script('database name', 'view name');  -- Backup for only particular view
    DECLARE errNom, RowNo INT DEFAULT 0;
    DECLARE errText VARCHAR(255) DEFAULT '';

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 errText = MESSAGE_TEXT, errNom = MYSQL_ERRNO;
        SELECT RowNo, errNom, errText, tableschema, ViewName;
    END;

    SET RowNo = 2;
    SELECT CONCAT(
        -- USE: unqualified functions in VIEW_DEFINITION are resolved in the view's own schema
        'USE `', TABLE_SCHEMA, '`;\n',
        'DROP VIEW IF EXISTS `', TABLE_SCHEMA, '`.`', TABLE_NAME, '`;\n',
        'CREATE OR REPLACE',
        -- DEFINER is 'user@host'; split on the LAST '@' (host part can never contain '@')
        ' DEFINER=`', LEFT(DEFINER, CHAR_LENGTH(DEFINER) - CHAR_LENGTH(SUBSTRING_INDEX(DEFINER, '@', -1)) - 1),
        '`@`', SUBSTRING_INDEX(DEFINER, '@', -1), '`',
        ' SQL SECURITY ', SECURITY_TYPE,
        ' VIEW `', TABLE_SCHEMA, '`.`', TABLE_NAME, '` AS ', VIEW_DEFINITION,
        IF(CHECK_OPTION = 'NONE', '', CONCAT(' WITH ', CHECK_OPTION, ' CHECK OPTION')),
        ';\n'
    ) AS fullscript
    FROM information_schema.VIEWS
    WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'ndbinfo', 'ndbmemcache', 'sys')
      AND (tableschema = '' OR TABLE_SCHEMA = tableschema)
      AND (ViewName    = '' OR TABLE_NAME   = ViewName);

END $$
DELIMITER ;
""",
'transformer.py': r"""import os
import re
import sys
import tempfile
from pathlib import Path

BT = chr(96)
PATTERN = re.compile(
    r"(?P<skip>\s+|--(?=\s|$)[^\r\n]*|\#[^\r\n]*|/\*.*?\*/)"
    r"|(?P<string>'(?:\\.|''|[^'\\])*'|\"(?:\\.|\"\"|[^\"\\])*\")"
    r"|(?P<session>@@?(?:" + BT + r"(?:" + BT*2 + r"|[^" + BT + r"])*" + BT + r"|[\w$]+))"
    r"|(?P<identifier>" + BT + r"(?:" + BT*2 + r"|[^" + BT + r"])*" + BT + r")"
    r"|(?P<word>[A-Za-z_$][\w$]*)|(?P<number>\d+)|(?P<symbol>.)",
    re.DOTALL,
)

def lex(sql):
    result = []
    for m in PATTERN.finditer(sql):
        if m.lastgroup == 'skip':
            continue
        if m.lastgroup == 'symbol' and m.group() in ("'", '"', BT):
            raise ValueError('Unterminated SQL literal or identifier')
        result.append((m.lastgroup, m.group(), m.start(), m.end()))
    return result

def name(token):
    return token[1].strip(BT).replace(BT*2, BT).lower()

def edit(sql, changes):
    boundary = len(sql) + 1
    for a, b, value in sorted(changes, reverse=True):
        if b > boundary:
            raise ValueError('Overlapping SQL edits')
        sql = sql[:a] + value + sql[b:]
        boundary = a
    return sql

def blocks(ts):
    stack, pairs = [], {}
    for i, t in enumerate(ts):
        if t[0] != 'word':
            continue
        w = name(t)
        prev = name(ts[i-1]) if i else ''
        after = name(ts[i+1]) if i+1 < len(ts) else ''
        if w in ('begin', 'case') and prev != 'end':
            stack.append((w, i))
        elif w == 'end' and after not in ('if', 'loop', 'while', 'repeat'):
            if stack:
                kind, start = stack.pop()
                if kind == 'begin':
                    pairs[start] = i
    return pairs

def handlers(ts, pairs):
    result = []
    for i in range(len(ts)-4):
        if (name(ts[i]) != 'declare' or name(ts[i+1]) not in ('exit','continue','undo')
                or name(ts[i+2]) != 'handler' or name(ts[i+3]) != 'for'):
            continue
        j = i+4
        while j < len(ts):
            if name(ts[j]) == 'sqlstate':
                j += 1
                if j < len(ts) and name(ts[j]) == 'value':
                    j += 1
                j += 1
            elif name(ts[j]) == 'not':
                j += 2
            else:
                j += 1
            if j < len(ts) and ts[j][1] == ',':
                j += 1
            else:
                break
        if j >= len(ts):
            raise ValueError('Incomplete handler')
        if name(ts[j]) == 'begin':
            if j not in pairs:
                raise ValueError('Unbalanced handler BEGIN/END')
            end = pairs[j]
        elif name(ts[j]) in ('if','case','while','loop','repeat'):
            raise ValueError('Please wrap compound handler statements in BEGIN/END')
        else:
            end = next((k for k in range(j,len(ts)) if ts[k][1] == ';'), len(ts)-1)
        result.append((j,end))
    return result

def column_positions(ts):
    # INSERT lists and UPDATE assignment targets are column names, not locals.
    positions = set()
    for i,t in enumerate(ts):
        if t[0] != 'word' or name(t) != 'insert':
            continue
        j = i+1
        while j < len(ts) and name(ts[j]) in ('ignore','into','low_priority','delayed','high_priority'):
            j += 1
        if j >= len(ts):
            continue
        j += 1
        while j+1 < len(ts) and ts[j][1] == '.':
            j += 2
        if j < len(ts) and ts[j][1] == '(':
            end = next((k for k in range(j+1,len(ts)) if ts[k][1] == ')'), j)
            positions.update(range(j+1,end))
    for i,t in enumerate(ts):
        if t[0] != 'word' or name(t) != 'update':
            continue
        j = i+1
        if i == 0 or name(ts[i-1]) != 'key':
            while j < len(ts) and name(ts[j]) != 'set' and ts[j][1] != ';':
                j += 1
            j += 1
        depth, lhs = 0, True
        while j < len(ts) and ts[j][1] != ';':
            if depth == 0 and name(ts[j]) in ('where','order','limit'):
                break
            if depth == 0 and lhs:
                positions.add(j)
                lhs = False
            if ts[j][1] == '(':
                depth += 1
            elif ts[j][1] == ')':
                depth -= 1
            elif depth == 0 and ts[j][1] == ',':
                lhs = True
            j += 1
    return positions

def migrate_errors(sql):
    ts = lex(sql)
    pairs = blocks(ts)
    hs = handlers(ts,pairs)
    inside = lambda k: any(a <= k <= b for a,b in hs)
    target = {'errnom':'@errNom','errtext':'@errText'}
    types = set(('tinyint smallint mediumint int integer bigint decimal numeric float double real '
                 'bit bool boolean char varchar binary varbinary tinytext text mediumtext longtext '
                 'tinyblob blob mediumblob longblob date time datetime timestamp year json enum set').split())
    declarations, names = [], set()
    for i,t in enumerate(ts):
        if t[0] != 'word' or name(t) != 'declare':
            continue
        j, ns = i+1, []
        while j < len(ts) and ts[j][0] in ('word','identifier'):
            ns.append(j)
            j += 1
            if j < len(ts) and ts[j][1] == ',':
                j += 1
            else:
                break
        if not ns or j >= len(ts) or name(ts[j]) not in types:
            continue
        end = next((k for k in range(j,len(ts)) if ts[k][1] == ';'),None)
        if end is None:
            raise ValueError('Unterminated DECLARE')
        scope = max(((a,b) for a,b in pairs.items() if a<i<b),
                    default=(-1,len(ts)),key=lambda x:x[0])
        declarations.append((i,end,ns,scope))
        names.update(ns)

    def binding(k,n):
        found = [(d[3][0],p) for d in declarations for p in d[2]
                 if name(ts[p]) == n and d[3][0] < k < d[3][1]]
        return max(found,default=(-2,None))[1]

    columns = column_positions(ts)
    def reference(k):
        return (k not in columns and k not in names
                and (k == 0 or name(ts[k-1]) not in ('.','as'))
                and (k+1 == len(ts) or ts[k+1][1] not in ('.','(')))

    migrated = set()
    for k,t in enumerate(ts):
        n = name(t).lstrip('@')
        if n in target and inside(k) and reference(k):
            p = binding(k,n)
            if p is not None:
                migrated.add(p)
    changes, deleted = [], []
    for a,b,ns,_ in declarations:
        if not any(p in migrated for p in ns):
            continue
        if all(p in migrated for p in ns):
            span = (ts[a][2],ts[b][3])
            changes.append((*span,''))
            deleted.append(span)
        else:
            k = 0
            while k < len(ns):
                if ns[k] not in migrated:
                    k += 1
                    continue
                first = k
                while k+1 < len(ns) and ns[k+1] in migrated:
                    k += 1
                span = ((ts[ns[first]][2],ts[ns[k]+1][3]) if k+1 < len(ns)
                        else (ts[ns[first]-1][2],ts[ns[k]][3]))
                changes.append((*span,''))
                deleted.append(span)
                k += 1
    for k,t in enumerate(ts):
        n = name(t)
        if (t[0] not in ('word','identifier') or n not in target or not reference(k)
                or any(a <= t[2] < b for a,b in deleted)):
            continue
        p = binding(k,n)
        # Follow removed bindings outside the handler too, avoiding dangling uses.
        if p in migrated or (p is None and inside(k)):
            changes.append((t[2],t[3],target[n]))
    return edit(sql,changes)

def convert_utf8_definitions(sql):
    if os.environ.get('CONVERT_UTF8_TO_UTF8MB4', '1') != '1':
        return sql
    ts = lex(sql)
    string_types = {'char', 'character', 'varchar', 'nchar', 'nvarchar', 'national',
                    'tinytext', 'text', 'mediumtext', 'longtext', 'enum', 'set'}
    ranges = []

    def type_range(start, end):
        if start >= end or ts[start][0] != 'word' or name(ts[start]) not in string_types:
            return
        # DEFAULT expressions can have their own meaningful COLLATE clauses.
        end = next((k for k in range(start, end)
                    if ts[k][0] == 'word' and name(ts[k]) == 'default'), end)
        ranges.append((start, end))

    def top_level_ranges(start, end, stop_words=()):
        # Column DEFAULT/generated expressions and partition expressions may
        # contain runtime COLLATE clauses. Only collect definition attributes.
        depth, run = 0, start
        for k in range(start, end):
            if ts[k][1] == '(':
                if depth == 0 and run < k:
                    ranges.append((run, k))
                depth += 1
            elif ts[k][1] == ')':
                depth -= 1
                if depth == 0:
                    run = k + 1
            elif depth == 0 and ts[k][0] == 'word' and name(ts[k]) in stop_words:
                if run < k:
                    ranges.append((run, k))
                return
        if depth == 0 and run < end:
            ranges.append((run, end))

    # Local variables, including a shared type for DECLARE a,b,c VARCHAR(...).
    for i, t in enumerate(ts):
        if t[0] != 'word' or name(t) != 'declare':
            continue
        j = i + 1
        while j < len(ts) and ts[j][0] in ('word', 'identifier'):
            j += 1
            if j < len(ts) and ts[j][1] == ',':
                j += 1
            else:
                break
        end = next((k for k in range(j, len(ts)) if ts[k][1] == ';'), len(ts))
        type_range(j, end)

    # Routine signatures plus CREATE [TEMPORARY] TABLE definitions in bodies.
    for i, t in enumerate(ts):
        if t[0] != 'word' or name(t) != 'create':
            continue
        kind = next((k for k in range(i + 1, len(ts))
                     if ts[k][0] == 'word' and name(ts[k]) in
                     ('procedure', 'function', 'table', 'view', 'trigger', 'event')
                     or ts[k][1] == ';'), None)
        if kind is None or name(ts[kind]) not in ('procedure', 'function', 'table'):
            continue
        if name(ts[kind]) == 'table':
            j = kind + 1
            if ([name(t) for t in ts[j:j + 3]] == ['if', 'not', 'exists']):
                j += 3
            if j >= len(ts) or ts[j][0] not in ('word', 'identifier'):
                continue
            j += 1  # table name, optionally qualified with a schema
            if j < len(ts) and ts[j][1] == '.':
                j += 2
            end = next((k for k in range(j, len(ts)) if ts[k][1] == ';'), len(ts))
            if j < end and ts[j][1] == '(':
                depth, start, closing = 1, j + 1, None
                for k in range(j + 1, end):
                    if ts[k][1] == '(':
                        depth += 1
                    elif ts[k][1] == ')':
                        depth -= 1
                    if depth == 0 or (depth == 1 and ts[k][1] == ','):
                        # Skip the column name; constraints/indexes have no
                        # string data type in this position.
                        column_type = start + 1
                        if (column_type < k and ts[column_type][0] == 'word'
                                and name(ts[column_type]) in string_types):
                            top_level_ranges(column_type, k,
                                             ('as', 'generated', 'check', 'references'))
                        start = k + 1
                    if depth == 0:
                        closing = k
                        break
                if closing is None:
                    raise ValueError('Unbalanced CREATE TABLE column definitions')
                j = closing + 1
            # DEFAULT CHARSET[=]utf8, [DEFAULT] CHARACTER SET [=] utf8,
            # and COLLATE[=]utf8_*; SELECT/LIKE contents remain expressions.
            top_level_ranges(j, end, ('as', 'select', 'like', 'partition'))
            continue
        j = kind + 2  # routine name
        if j < len(ts) and ts[j][1] == '.':
            j += 2
        if j >= len(ts) or ts[j][1] != '(':
            continue
        depth, start, closing = 1, j + 1, None
        for k in range(j + 1, len(ts)):
            if ts[k][1] == '(':
                depth += 1
            elif ts[k][1] == ')':
                depth -= 1
            if depth == 0 or (depth == 1 and ts[k][1] == ','):
                parameter = start
                if parameter < k and name(ts[parameter]) in ('in', 'out', 'inout'):
                    parameter += 1
                type_range(parameter + 1, k)  # skip the parameter name
                start = k + 1
            if depth == 0:
                closing = k
                break
        if (closing is not None and name(ts[kind]) == 'function'
                and closing + 1 < len(ts) and name(ts[closing + 1]) == 'returns'):
            start = closing + 2
            stops = {'language', 'deterministic', 'not', 'contains', 'no', 'reads',
                     'modifies', 'sql', 'comment', 'begin', 'return'}
            end = next((k for k in range(start, len(ts))
                        if ts[k][1] == ';' or
                        (ts[k][0] == 'word' and name(ts[k]) in stops)), len(ts))
            type_range(start, end)

    def value(t):
        return t[1][1:-1].lower() if t[0] == 'string' else name(t)

    # Legacy collation families with a corresponding utf8mb4 collation in
    # MySQL 8.4. Do not manufacture a target for an unknown/custom collation.
    collation_suffixes = {
        'bin', 'general_ci', 'unicode_ci', 'unicode_520_ci', 'icelandic_ci',
        'latvian_ci', 'romanian_ci', 'slovenian_ci', 'polish_ci', 'estonian_ci',
        'spanish_ci', 'swedish_ci', 'turkish_ci', 'czech_ci', 'danish_ci',
        'lithuanian_ci', 'slovak_ci', 'spanish2_ci', 'roman_ci', 'persian_ci',
        'esperanto_ci', 'hungarian_ci', 'sinhala_ci', 'german2_ci',
        'croatian_ci', 'vietnamese_ci',
    }

    changes = []
    for start, end in ranges:
        i = start
        while i < end:
            j = i
            if ts[i][0] != 'word':
                i += 1
                continue
            word = name(ts[i])
            if word == 'character' and i + 1 < end and name(ts[i + 1]) == 'set':
                j = i + 2
            elif word in ('charset', 'collate'):
                j = i + 1
            else:
                i += 1
                continue
            if j < end and ts[j][1] == '=':
                j += 1
            pattern = r'utf8(?:mb3)?_([a-z0-9_]+)' if word == 'collate' else r'utf8(?:mb3)?'
            if (j >= end or ts[j][0] not in ('word', 'identifier', 'string')
                    or not re.fullmatch(pattern, value(ts[j]))):
                i += 1
                continue
            replacement = 'utf8mb4'
            if word == 'collate':
                suffix = re.fullmatch(pattern, value(ts[j])).group(1)
                if suffix not in collation_suffixes:
                    raise ValueError('No verified utf8mb4 equivalent for collation '
                                     + value(ts[j]) + '; choose its target explicitly')
                replacement += '_' + suffix
            # Replace only the value token, retaining quotes and every comment.
            if ts[j][0] in ('identifier', 'string'):
                replacement = ts[j][1][0] + replacement + ts[j][1][-1]
            changes.append((ts[j][2], ts[j][3], replacement))
            i = j + 1
    return edit(sql, changes)

def remove_group_by_desc(sql):
    if os.environ.get('REMOVE_GROUP_BY_DESC', '1') != '1':
        return sql
    ts = lex(sql)
    depths, depth = [], 0
    for t in ts:
        depths.append(depth)
        if t[1] == '(':
            depth += 1
        elif t[1] == ')':
            depth -= 1

    def keyword(k, words):
        return (k < len(ts) and ts[k][0] == 'word' and name(ts[k]) in words
                and (k == 0 or ts[k - 1][1] != '.'))

    def group_boundary(k):
        if keyword(k, ('order',)):
            return keyword(k + 1, ('by',))
        if keyword(k, ('window',)):
            return keyword(k + 2, ('as',))
        if keyword(k, ('with',)):
            return keyword(k + 1, ('rollup',))
        return keyword(k, ('having', 'limit', 'into', 'for', 'lock'))

    changes = []
    for i in range(len(ts) - 1):
        if not keyword(i, ('group',)) or not keyword(i + 1, ('by',)):
            continue
        level = depths[i]
        query_end = next((k for k in range(i + 2, len(ts))
                          if depths[k] == level and
                          (ts[k][1] in (';', ')') or
                           keyword(k, ('union', 'except', 'intersect')))), len(ts))
        group_end = next((k for k in range(i + 2, query_end)
                          if depths[k] == level and group_boundary(k)), query_end)
        items, start = [], i + 2
        for k in range(start, group_end):
            if depths[k] == level and ts[k][1] == ',':
                items.append((start, k))
                start = k + 1
        items.append((start, group_end))
        for a, b in items:
            last = b - 1
            if (last <= a or depths[last] != level or ts[last][0] != 'word'
                    or name(ts[last]) != 'desc' or ts[last - 1][1] == '.'):
                continue
            # Remove DESC and adjacent whitespace, retaining every comment.
            gap = sql[ts[last - 1][3]:ts[last][2]]
            delete_start = ts[last - 1][3] if not gap.strip() else ts[last][2]
            changes.append((delete_start, ts[last][3], ''))
    return edit(sql, changes)


def transform(sql):
    sql = migrate_errors(sql)
    sql = convert_utf8_definitions(sql)
    sql = remove_group_by_desc(sql)
    ts, changes = lex(sql), []
    quoted = set(os.environ.get('QUOTE_IDENTIFIERS','over groups').lower().split())
    parens, windows = [], set()
    for i,t in enumerate(ts):
        prev = name(ts[i-1]) if i else ''
        after = name(ts[i+1]) if i+1 < len(ts) else ''
        w = name(t)
        if t[1] == '(':
            parens.append(i)
            if prev == 'over' and i >= 2 and ts[i-2][1] == ')':
                windows.add(i)
        elif t[1] == ')' and parens:
            windows.discard(parens.pop())
        if t[0] == 'word' and w == 'regexp' and after == 'binary' and ts[i+1][0] == 'word':
            changes.append((ts[i+1][2],ts[i+1][3],''))
        if t[0] != 'word' or w not in quoted:
            continue
        callable_words = {'rank','dense_rank','row_number','cume_dist','percent_rank',
                          'ntile','lag','lead','first_value','last_value','nth_value'}
        genuine = ((after == '(' and w in callable_words)
                   or (w == 'over' and prev == ')')
                   or (w == 'lateral' and after == '(')
                   or (w == 'recursive' and prev == 'with')
                   or (w == 'window' and i+2<len(ts) and name(ts[i+2]) == 'as')
                   or (w == 'groups' and windows and
                       (after in ('between','unbounded','current') or
                        (i+1<len(ts) and ts[i+1][0] == 'number'))))
        if not genuine:
            changes.append((t[2],t[3],BT+t[1]+BT))
    return edit(sql,changes)

""",
}



class BackupError(Exception):
    pass


def decode_batch_field(value):
    """Undo exactly one layer of mysql --batch escaping, retaining SQL escapes."""
    escapes = {'n': '\n', 't': '\t', '0': '\0', '\\': '\\'}
    return re.sub(r'\\([nt0\\])', lambda m: escapes[m[1]], value)


def parse_batch_rows(text, context, required_columns=()):
    """Decode mysql --batch fields, without treating SQL text as XML or Python escapes.

    The client escapes LF, TAB, NUL and backslash. A literal SQL \\n arrives as
    \\\\n, so only one decoding pass is correct. CR and other control characters
    can remain literal: split on LF only, never str.splitlines().
    """
    if not text:
        return []
    lines = text.split('\n')
    if lines[-1] == '':
        lines.pop()
    headers = lines[0].split('\t')
    if not all(headers) or len(set(headers)) != len(headers):
        raise BackupError(f'{context}: invalid column headers from mysql --batch.')
    missing = set(required_columns) - set(headers)
    if missing:
        raise BackupError(f'{context}: mysql --batch did not return expected columns: '
                          + ', '.join(sorted(missing)) + '. Export stopped.')
    result = []
    for number, line in enumerate(lines[1:], start=1):
        fields = line.split('\t')
        if len(fields) != len(headers):
            raise BackupError(f'{context}: invalid mysql --batch row {number}: '
                              f'expected {len(headers)} columns, received {len(fields)}. '
                              'Export stopped; no SQL text was discarded.')
        result.append({header: decode_batch_field(value)
                       for header, value in zip(headers, fields)})
    return result


def prompt(label, default=None, required=False):
    while True:
        value = input(label + (f' [{default}]' if default is not None else '') + ': ').strip()
        value = value or (str(default) if default is not None else '')
        if value or not required:
            return value
        print('Please enter a value.')


def yes(label):
    return prompt(label + ' (y/N)').lower() in ('y', 'yes')


def ident(value):
    return '`' + value.replace('`', '``') + '`'


def literal(value):
    return 'CONVERT(0x' + value.encode('utf-8').hex() + ' USING utf8mb4)' if value else "''"


def safe_filename(value):
    cleaned = re.sub(r'[^A-Za-z0-9_.-]', '_', value).strip('.')[:100] or 'backup'
    if cleaned != value:
        cleaned += '-' + hashlib.sha256(value.encode()).hexdigest()[:10]
    return cleaned


def command(args, **kwargs):
    try:
        result = subprocess.run(args, stderr=subprocess.PIPE, **kwargs)
    except OSError as error:
        raise BackupError(str(error)) from error
    if result.returncode:
        message = result.stderr.decode('utf-8', errors='replace').strip()
        raise BackupError(message or f'{args[0]} failed (exit {result.returncode})')
    if result.stderr:
        print(result.stderr.decode('utf-8', errors='replace').strip(), file=sys.stderr)
    return result


def transform_sql(sql):
    namespace = {}
    exec(compile(RESOURCES['transformer.py'], 'embedded-transformer.py', 'exec'), namespace)
    return namespace['transform'](sql)


def generator_sql(names=GENERATORS):
    # The client's delimiter directives are intentionally retained in the bundle.
    parts = ['CREATE DATABASE IF NOT EXISTS `tools` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;',
             'USE `tools`;', 'SET @FLEX_OLD_SQL_MODE=@@SESSION.sql_mode;',
             "SET SESSION sql_mode='NO_ENGINE_SUBSTITUTION';"]
    for name in names:
        sql = RESOURCES[name + '.sql']
        # Only the CREATE PROCEDURE prefix: preserve DEFINER text emitted into backups.
        sql = re.sub(r'CREATE\s+DEFINER=`Sup_User_SPESA`@`%`\s+PROCEDURE',
                     'CREATE DEFINER=CURRENT_USER PROCEDURE', sql, count=1, flags=re.I)
        # Helpers must propagate errors; a diagnostic SELECT falsely looks like an SQL backup.
        sql = re.sub(r'(GET DIAGNOSTICS CONDITION 1[^;]*;\s*)SELECT[^;]*;',
                     r'\1RESIGNAL;', sql, count=1, flags=re.I)
        sql = re.sub(r'\butf8_general_ci\b', 'utf8mb4_general_ci', sql, flags=re.I)
        sql = re.sub(r'\butf8\b', 'utf8mb4', sql, flags=re.I)
        # VARCHAR(21845) fits three-byte utf8, but exceeds 65535 bytes in utf8mb4.
        sql = re.sub(r'\bSchemaNames VARCHAR\(21845\)', 'SchemaNames TEXT', sql, flags=re.I)
        parts.append(sql)
    parts.append('SET SESSION sql_mode=@FLEX_OLD_SQL_MODE;')
    return '\n\n'.join(parts) + '\n'


class Client:
    def __init__(self, host, port, user, password, output):
        self.env = dict(os.environ, MYSQL_PWD=password, MYSQL_TEST_LOGIN_FILE='/dev/null')
        self.base = ['--no-defaults', '--default-character-set=utf8mb4', '--protocol=TCP',
                     '--host=' + host, '--port=' + port, '--user=' + user]
        self.mysql = ['mysql', *self.base, '--batch',
                      '--init-command=SET NAMES utf8mb4 COLLATE utf8mb4_general_ci']
        self.output = Path(output).expanduser().resolve()
        self.host = host

    def query(self, sql, rows=False, context=None, required_columns=()):
        context = context or ('MySQL query: ' + sql.split('\n', 1)[0][:160])
        result = command([*self.mysql, '--execute', sql],
                         env=self.env, stdout=subprocess.PIPE)
        try:
            text = result.stdout.decode('utf-8')
        except UnicodeDecodeError as error:
            raise BackupError(f'{context}: mysql returned invalid UTF-8 at byte {error.start}; export stopped.') from error
        if not rows:
            return text
        return parse_batch_rows(text, context, required_columns)

    def install(self, names):
        if not names:
            return
        print('Installing in tools: ' + ', '.join(names))
        command(self.mysql, input=generator_sql(names).encode('utf-8'), env=self.env,
                stdout=subprocess.PIPE)
        present = self.present()
        missing = set(names) - present
        if missing:
            raise BackupError('Installation incomplete: ' + ', '.join(sorted(missing)))
        print('Generator installation completed.')

    def present(self):
        rows = self.query("SELECT ROUTINE_NAME FROM information_schema.ROUTINES "
                          "WHERE ROUTINE_SCHEMA='tools' AND ROUTINE_TYPE='PROCEDURE'", rows=True,
                          required_columns=('ROUTINE_NAME',))
        return {row['ROUTINE_NAME'] for row in rows}

    def ensure(self, name):
        if name in self.present():
            return True
        print(f'Missing generator: tools.{name}')
        if not yes('Install this bundled generator now'):
            return False
        self.install([name])
        return True

    def directory(self, category):
        self.output.mkdir(parents=True, exist_ok=True)
        stamp = datetime.datetime.now().strftime('%Y%m%d_%H%M%S_')
        folder = Path(tempfile.mkdtemp(prefix=safe_filename(self.host) + '_' + stamp + category + '_',
                                       dir=self.output))
        return folder

    def definitions(self, generator, arguments, category):
        if generator == 'gen_event_script':
            schema, event = arguments
            conditions = ["EVENT_TYPE<>'RECURRING'"]
            if schema:
                conditions.append('EVENT_SCHEMA=' + literal(schema))
            if event:
                conditions.append('EVENT_NAME=' + literal(event))
            unsupported = self.query('SELECT EVENT_SCHEMA,EVENT_NAME FROM information_schema.EVENTS WHERE '
                                     + ' AND '.join(conditions), rows=True,
                                     required_columns=('EVENT_SCHEMA', 'EVENT_NAME'))
            if unsupported:
                raise BackupError('The legacy event generator cannot export one-time events. '
                                  'Export stopped to avoid silently omitting: ' + ', '.join(
                                      r['EVENT_SCHEMA'] + '.' + r['EVENT_NAME'] for r in unsupported))
        if not self.ensure(generator):
            return
        raw = self.query('CALL tools.' + generator + '(' + ','.join(
            str(a) if isinstance(a, int) else literal(a) for a in arguments) + ');')
        header = raw.split('\n', 1)[0] if raw else ''
        if re.search(r'\b(errNom|errText|res)\b', header, flags=re.I):
            raise BackupError('The installed generator returned diagnostics, not SQL:\n' + raw[:1200])
        if not raw:
            print('No matching objects returned. No backup file was created.')
            return
        if '\t' in header:
            raise BackupError(f'Exporting {category}: expected one SQL result column from {generator}.')
        # Retain sed header removal. Decode complete batch fields afterwards:
        # expanding only \\n leaves \\t active as mysql's notee command and can
        # corrupt literal SQL escape sequences. Do not decode the result twice.
        data = command(['sed', '1d'], input=raw.encode('utf-8'), stdout=subprocess.PIPE).stdout.decode('utf-8')
        lines = data.split('\n')
        if lines[-1] == '':
            lines.pop()
        statements = []
        for number, line in enumerate(lines, start=1):
            if '\t' in line:
                raise BackupError(f'Exporting {category}: unexpected result columns in row {number}.')
            if line == 'NULL':
                continue
            statements.append(decode_batch_field(line))
        data = '\n'.join(statements).encode('utf-8')
        if not data.strip():
            print('No matching objects returned. No backup file was created.')
            return
        if not data.endswith(b'\n'):
            data += b'\n'
        folder = self.directory(category)
        path = folder / (category + '.sql')
        try:
            path.write_bytes(data)
        except OSError:
            path.unlink(missing_ok=True)
            raise
        print(f'Saved: {path}')

    def routines(self, schema, routine, migrate):
        patterns = json.loads(os.environ.get('EXCLUDE_SP_PATTERNS_JSON', json.dumps(DEFAULT_PATTERNS)))
        schemas = json.loads(os.environ.get('EXCLUDED_SCHEMAS_JSON', '[]'))
        if not isinstance(patterns, list) or not isinstance(schemas, list) or any(
                not isinstance(v, str) for v in patterns + schemas):
            raise BackupError('Routine exclusion settings must be JSON arrays of strings.')
        digits = int(os.environ.get('MAX_DIGITS_IN_NAME', '5'))
        if digits < 0:
            raise BackupError('MAX_DIGITS_IN_NAME must be nonnegative.')
        conditions = ['ROUTINE_SCHEMA NOT IN (' + ','.join(literal(s) for s in SYSTEM_SCHEMAS) + ')']
        if schema:
            conditions.append('ROUTINE_SCHEMA=' + literal(schema))
        if routine:
            conditions.append('ROUTINE_NAME=' + literal(routine))
        conditions += ['ROUTINE_NAME NOT LIKE ' + literal(p) for p in patterns]
        conditions += ['ROUTINE_SCHEMA<>' + literal(s) for s in schemas]
        if digits:
            conditions.append("ROUTINE_NAME NOT REGEXP '[0-9]" + '.*[0-9]' * (digits - 1) + "'")
        rows = self.query('SELECT ROUTINE_SCHEMA,ROUTINE_NAME,ROUTINE_TYPE FROM information_schema.ROUTINES WHERE '
                          + ' AND '.join(conditions) + ' ORDER BY ROUTINE_SCHEMA,ROUTINE_NAME',
                          rows=True, context='Reading the stored procedure/function list',
                          required_columns=('ROUTINE_SCHEMA', 'ROUTINE_NAME', 'ROUTINE_TYPE'))
        if not rows:
            print('No routines matched (including the configured exclusions).')
            return
        folder = self.directory('routines')
        path = folder / 'routines.sql'
        temp = folder / 'routines.sql.partial'
        try:
            with temp.open('w', encoding='utf-8', newline='') as stream:
                for row in rows:
                    kind, db, name = row['ROUTINE_TYPE'], row['ROUTINE_SCHEMA'], row['ROUTINE_NAME']
                    if kind not in ('PROCEDURE', 'FUNCTION'):
                        raise BackupError('Unexpected routine type: ' + str(kind))
                    result = self.query(f'SHOW CREATE {kind} {ident(db)}.{ident(name)}', rows=True,
                                        context=f'Reading {kind} {ident(db)}.{ident(name)}',
                                        required_columns=('Create ' + kind.title(),))
                    create = result[0].get('Create ' + kind.title()) if result else None
                    if not create or create == 'NULL':
                        raise BackupError('SHOW CREATE returned no body for ' + db + '.' + name)
                    # Unique delimiter avoids collisions with tokens inside the original body.
                    delimiter = ';;'
                    while delimiter in create:
                        delimiter += ';'
                    sql = (f'USE {ident(db)};\nDROP {kind} IF EXISTS {ident(name)};\n'
                           f'DELIMITER {delimiter}\n{create}\n{delimiter}\nDELIMITER ;\n\n')
                    stream.write(transform_sql(sql) if migrate else sql)
            temp.replace(path)
        except BaseException:
            temp.unlink(missing_ok=True)
            raise
        print(f'Saved {len(rows)} routines: {path}')

    def data(self, schema, table, engine):
        if not shutil.which('mysqldump'):
            raise BackupError('mysqldump is required for data backups.')
        # Preserve gen_data_script dump flags, but select actual tables so EngineName
        # cannot silently produce a whole-schema backup. Never execute generated shell text.
        conditions = ["TABLE_SCHEMA NOT IN ('information_schema','performance_schema','mysql','ndbinfo','sys','ndbmemcache','_development','_test')",
                      "TABLE_TYPE='BASE TABLE'"]
        for column, value in [('TABLE_SCHEMA', schema), ('TABLE_NAME', table), ('ENGINE', engine)]:
            if value:
                conditions.append(column + '=' + literal(value))
        rows = self.query('SELECT TABLE_SCHEMA,TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE '
                          + ' AND '.join(conditions) + ' ORDER BY TABLE_SCHEMA,TABLE_NAME', rows=True,
                          required_columns=('TABLE_SCHEMA', 'TABLE_NAME', 'ENGINE'))
        if not rows:
            print('No matching tables. No data backup was created.')
            return
        groups = collections.defaultdict(list)
        for row in rows:
            groups[row['TABLE_SCHEMA']].append((row['TABLE_NAME'], row['ENGINE']))
        help_text = command(['mysqldump', '--no-defaults', '--help'], env=self.env,
                            stdout=subprocess.PIPE).stdout.decode('utf-8', errors='replace')
        flags = ['--no-create-db', '--no-create-info', '--skip-triggers', '--extended-insert', '--no-tablespaces']
        if 'column-statistics' in help_text:
            flags.append('--column-statistics=0')
        folder = self.directory('data')
        completed = []
        try:
            for db, tables in groups.items():
                path = folder / (safe_filename(db) + '_data.sql')
                temp = path.with_suffix('.sql.partial')
                with temp.open('wb') as stream:
                    # Without --databases: following arguments are tables, not more databases.
                    stream.write(('USE ' + ident(db) + ';\n').encode('utf-8'))
                    command(['mysqldump', *self.base, *flags, '--', db,
                             *[name for name, _ in tables]], env=self.env, stdout=stream)
                temp.replace(path)
                completed.append(path)
        except BaseException:
            for partial in folder.glob('*.partial'):
                partial.unlink()
            print(f'Data backup incomplete. Completed schema files: {len(completed)}. Folder: {folder}', file=sys.stderr)
            raise
        print(f'Saved {len(completed)} data files: {folder}')
        print('Data-only export; restore schema and table structures first. '
              'Separate dumps do not provide a coordinated snapshot across schemas or NDB tables.')


def scope(label):
    print(f'\n{label}\n1. All databases\n2. One database\n3. One object\n0. Back')
    choice = prompt('Choice')
    if choice == '0':
        return None
    if choice not in ('1', '2', '3'):
        raise BackupError('Invalid choice.')
    db = prompt('Database name', required=True) if choice != '1' else ''
    name = prompt('Object name', required=True) if choice == '3' else ''
    return db, name


def table_options(client, data=False):
    selected = scope('Table data' if data else 'Table structures')
    if selected is None:
        return
    db, table = selected
    engine = prompt('Engine filter (blank = all)')
    # Table generator internally interpolates EngineName into dynamic SQL.
    if engine and not re.fullmatch(r'[A-Za-z0-9_]+', engine):
        raise BackupError('Engine must contain only letters, numbers and underscores.')
    if data:
        client.data(db, table, engine)
        return
    charset = prompt('Target character set (blank = preserve)')
    collation = prompt('Target collation (blank = preserve)')
    if charset and not re.fullmatch(r'[A-Za-z0-9_]+', charset):
        raise BackupError('Invalid character set name.')
    if collation and not re.fullmatch(r'[A-Za-z0-9_]+', collation):
        raise BackupError('Invalid collation name.')
    if bool(charset) != bool(collation):
        raise BackupError('Enter both target charset and collation, or leave both blank.')
    if charset:
        rows = client.query('SELECT COLLATION_NAME FROM information_schema.COLLATIONS WHERE COLLATION_NAME='
                            + literal(collation) + ' AND CHARACTER_SET_NAME=' + literal(charset), rows=True,
                            required_columns=('COLLATION_NAME',))
        if not rows:
            raise BackupError('The selected charset/collation pair is not available on the source server.')
    # The legacy table generator embeds schema names into dynamic quoted SQL.
    # Validate all selected schema names before invoking it.
    schema_rows = client.query('SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE '
                               + ('SCHEMA_NAME=' + literal(db) if db else 'SCHEMA_NAME NOT IN (' + ','.join(literal(s) for s in SYSTEM_SCHEMAS) + ')'), rows=True,
                               required_columns=('SCHEMA_NAME',))
    if any(not re.fullmatch(r'[A-Za-z0-9_$-]+', r['SCHEMA_NAME']) for r in schema_rows):
        raise BackupError('This legacy table generator requires simple database names (letters, numbers, _, $, -).')
    # Legacy GROUP_CONCAT iteration uses commas as separators; reject ambiguous names.
    name_rows = client.query('SELECT TABLE_NAME FROM information_schema.TABLES WHERE '
                             + ('TABLE_SCHEMA=' + literal(db) if db else 'TABLE_SCHEMA NOT IN (' + ','.join(literal(s) for s in SYSTEM_SCHEMAS) + ')')
                             + (' AND TABLE_NAME=' + literal(table) if table else '')
                             + " AND TABLE_TYPE='BASE TABLE'" + (' AND ENGINE=' + literal(engine) if engine else ''), rows=True,
                             required_columns=('TABLE_NAME',))
    if not name_rows:
        print('No matching tables.')
        return
    if any(',' in r['TABLE_NAME'] for r in name_rows):
        raise BackupError('The legacy table generator cannot safely process table names containing commas.')
    client.definitions('gen_table_script', [1, db, table, engine, charset, collation], 'tables')


def interactive(args):
    for executable in ('mysql', 'sed'):
        if not shutil.which(executable):
            raise BackupError(executable + ' is required.')
    if 'GNU sed' not in command(['sed', '--version'], stdout=subprocess.PIPE).stdout.decode(errors='replace'):
        raise BackupError('GNU sed is required by the original export pipelines.')
    print('flexmysqlbackup ' + VERSION + ' — interactive SQL exports')
    host = args.host or prompt('MySQL host', os.environ.get('MYSQL_HOST', 'localhost'))
    port = args.port or prompt('MySQL port', os.environ.get('MYSQL_PORT', '3306'))
    user = args.user or prompt('MySQL user', os.environ.get('MYSQL_USER', 'devops'))
    if not port.isdigit() or not 1 <= int(port) <= 65535:
        raise BackupError('Invalid TCP port.')
    password = getpass.getpass('MySQL password: ')
    output = args.output or prompt('Output directory', './backups')
    client = Client(host, port, user, password, output)
    info = client.query('SELECT VERSION() AS version, CURRENT_USER() AS account', rows=True,
                        required_columns=('version', 'account'))
    print('Connected: ' + str(info[0].get('account')) + ' — MySQL ' + str(info[0].get('version')))
    while True:
        print('\n1. Schemas (databases)\n2. Table structures\n3. Table data\n4. Views\n'
              '5. Stored procedures and functions\n6. Triggers\n7. Events\n'
              '8. Install/update bundled generators\n0. Exit')
        choice = prompt('Choice')
        try:
            if choice == '0':
                break
            if choice == '1':
                print('\n1. All schemas selected by the generator\n2. One schema\n0. Back')
                sub = prompt('Choice')
                if sub == '0':
                    continue
                if sub not in ('1', '2'):
                    raise BackupError('Invalid choice.')
                db = prompt('Database name', required=True) if sub == '2' else ''
                client.definitions('gen_schemes_script', [db], 'schemas')
            elif choice in ('2', '3'):
                table_options(client, data=choice == '3')
            elif choice in ('4', '5', '6', '7'):
                selected = scope({'4':'Views', '5':'Routines', '6':'Triggers', '7':'Events'}[choice])
                if selected is None:
                    continue
                if choice == '5':
                    print('\n1. Apply process_sql_opt migration transformations\n2. Export original definitions')
                    mode = prompt('Choice', '1')
                    if mode not in ('1', '2'):
                        raise BackupError('Invalid choice.')
                    client.routines(*selected, migrate=mode == '1')
                else:
                    if choice == '6' and any("'" in s or '\\' in s for s in selected):
                        raise BackupError('The legacy trigger generator cannot safely filter names containing quotes or backslashes.')
                    generator, category = {'4':('gen_view_script','views'), '6':('gen_triggers_script','triggers'),
                                           '7':('gen_event_script','events')}[choice]
                    client.definitions(generator, list(selected), category)
            elif choice == '8':
                present = client.present()
                missing = [name for name in GENERATORS if name not in present]
                print('Missing: ' + (', '.join(missing) or 'none'))
                print('1. Install missing generators\n2. Replace all six generators\n0. Back')
                action = prompt('Choice')
                if action == '1':
                    client.install(missing)
                elif action == '2':
                    if yes('Replace only these six tools procedures with the bundled versions'):
                        client.install(GENERATORS)
                elif action != '0':
                    raise BackupError('Invalid choice.')
            else:
                print('Invalid choice.')
        except (BackupError, OSError, ValueError) as error:
            print('ERROR: ' + str(error), file=sys.stderr)


def main():
    os.umask(0o077)
    parser = argparse.ArgumentParser(prog='flexmysqlbackup.sh', description='Single-file flexmysqlbackup installer and interactive exporter.')
    parser.add_argument('--version', action='version', version=VERSION)
    parser.add_argument('--host')
    parser.add_argument('--port')
    parser.add_argument('--user')
    parser.add_argument('--output', help='Backup output directory')
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument('--transform', nargs='+', metavar='SQL_FILE', help='Offline: input.sql [output.sql]')
    modes.add_argument('--extract-install-sql', metavar='PATH', help='Write combined installer without connecting')
    args = parser.parse_args()
    if args.transform:
        if len(args.transform) not in (1, 2):
            parser.error('--transform requires input.sql [output.sql]')
        source = Path(args.transform[0])
        path = Path(args.transform[-1])
        result = transform_sql(source.read_bytes().decode('utf-8'))
        fd, temp = tempfile.mkstemp(prefix='.flex-transform-', dir=path.parent)
        try:
            with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
                stream.write(result)
            os.replace(temp, path)
        finally:
            if os.path.exists(temp):
                os.unlink(temp)
        return
    if args.extract_install_sql:
        with open(args.extract_install_sql, 'x', encoding='utf-8', newline='') as stream:
            stream.write(generator_sql())
        print('Saved installer: ' + args.extract_install_sql)
        return
    interactive(args)


if __name__ == '__main__':
    try:
        main()
    except (BackupError, OSError, ValueError) as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)
    except (EOFError, KeyboardInterrupt):
        print('\nCancelled.', file=sys.stderr)
        sys.exit(130)

FLEXMYSQLBACKUP_PYTHON
